{
  "name": "vechain-ai",
  "version": "1.0.0",
  "owner": {
    "name": "VeChain",
    "email": "developers@vechain.org"
  },
  "metadata": {
    "description": "VeChain-specific AI tools (skills, plugins, agents) for developers and AI agents building on the VeChainThor blockchain.",
    "repository": "https://github.com/vechain/vechain-ai-skills"
  },
  "plugins": [
    {
      "name": "vechain-dev",
      "source": {
        "source": "github",
        "repo": "vechain/vechain-ai-skills"
      },
      "description": "Full-stack VeChain development — dApps, smart contracts, fee delegation, testing, security, and DeFi ecosystem (VeBetterDAO, StarGate, governance)"
    },
    {
      "name": "karpathy-guidelines",
      "source": {
        "source": "github",
        "repo": "vechain/vechain-ai-skills"
      },
      "description": "Behavioral guidelines to reduce common LLM coding mistakes — surface assumptions, surgical changes, simplicity first, verifiable success criteria"
    },
    {
      "name": "translate",
      "source": {
        "source": "github",
        "repo": "vechain/vechain-ai-skills"
      },
      "description": "Manages react-i18next translation files across 15 languages — adds/removes keys, keeps files sorted, enforces fixed-word rules, verifies sync"
    },
    {
      "name": "grill-me",
      "source": {
        "source": "github",
        "repo": "vechain/vechain-ai-skills"
      },
      "description": "Interview you relentlessly about every aspect of a plan until shared understanding — walks the design tree, resolves dependencies one-by-one"
    },
    {
      "name": "prd",
      "source": {
        "source": "github",
        "repo": "vechain/vechain-ai-skills"
      },
      "description": "Generate a Product Requirements Document (PRD) for a new feature — clear, actionable, and suitable for implementation"
    },
    {
      "name": "ralph",
      "source": {
        "source": "github",
        "repo": "vechain/vechain-ai-skills"
      },
      "description": "Autonomous agent runner that implements features from PRDs — converts PRDs to prd.json, executes user stories one at a time via Claude CLI"
    }
  ]
}
